import sys
import math
import copy

def getInput(num):
	if num:
		inputArr = input().split()
		if len(inputArr) != num:
			print(f'The length is {len(inputArr)} not same as asked for {num}')
			sys.exit(0)
		for i in range(0, len(inputArr)):
			inputArr[i] = int(inputArr[i])
		return inputArr
	elif num == 0:
		return int(input())
	elif num == None:
		inputArr = input().split()
		for i in range(0, len(inputArr)):
			inputArr[i] = int(inputArr[i])
		return inputArr
remArr = [3, 8, 15, 24, 35, 48, 63, 80]
remDict = {}

def isLess(arr0, arr1):
	sum = 0
	tempArr = []
	for i in range(0, 8):
		myVal0 = arr1[i] - arr0[i]
		sum += myVal0
		tempArr.append(myVal0)
	if sum > 0:
		return True
	elif sum < 0:
		return False
	else:
		for i in range(0, 8):
			if tempArr[i] < 0:
				return True
			elif tempArr[i] > 0:
				return False
		else:
			return False

def getRemIndices(tRem):
	if tRem in remDict:
		return copy.deepcopy(remDict[tRem])
	if tRem < 3:
		remDict[tRem] = []
		return []
	indArr = []
	myTempArr = [0, 0, 0, 0, 0, 0, 0, 0]
	for i in range(0, 8):
		if remArr[i] == tRem:
			myTempArr[i] += 1
			return myTempArr
		elif remArr[i] < tRem:
			retArr = getRemIndices(tRem - remArr[i])
			if retArr:
				retArr[i] += 1
			if indArr and retArr:
				if isLess(retArr, indArr):
					indArr = copy.deepcopy(retArr)
			elif retArr:
				indArr = retArr
	remDict[tRem] = copy.deepcopy(indArr)
	return indArr
